  1	package com.loja.orderservice.service;
  2	
  3	import com.loja.orderservice.dto.CheckoutRequest;
  4	import com.loja.orderservice.entity.OrderSummary;
  5	import com.loja.orderservice.entity.Product;
  6	import com.loja.orderservice.exception.BusinessException;
  7	import com.loja.orderservice.model.*;
  8	import com.loja.orderservice.repository.OrderRepository;
  9	import com.loja.orderservice.repository.ProductRepository;
 10	import org.springframework.http.HttpStatus;
 11	import org.springframework.stereotype.Service;
 12	
 13	import java.math.BigDecimal;
 14	import java.math.RoundingMode;
 15	import java.util.*;
 16	
 17	@Service
 18	public class CheckoutCalculator {
 19	
 20	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 21	
 22	    private final ProductRepository productRepository;
 23	    private final OrderRepository orderRepository;
 24	    private final TransLogService transLogService;
 25	
 26	    public CheckoutCalculator(ProductRepository productRepository,
 27	                              OrderRepository orderRepository,
 28	                              TransLogService transLogService) {
 29	        this.productRepository = productRepository;
 30	        this.orderRepository = orderRepository;
 31	        this.transLogService = transLogService;
 32	    }
 33	
 34	    public OrderSummary calculate(CheckoutRequest request) {
 35	        validateRequest(request);
 36	
 37	        Map<String, Product> productMap = loadProducts(request);
 38	        Map<String, Integer> itemQuantities = getItemQuantities(request);
 39	
 40	        validateProducts(productMap, itemQuantities);
 41	
 42	        BigDecimal productsSubtotal = calculateProductsSubtotal(productMap, itemQuantities);
 43	
 44	        ShippingInfo shippingInfo = calculateShipping(request, productMap, itemQuantities);
 45	
 46	        BigDecimal shippingCost = shippingInfo.cost;
 47	        if (request.getClubTier() == ClubTier.GOLD && request.getShippingMethod() != ShippingMethod.COURIER) {
 48	            shippingCost = ZERO;
 49	        }
 50	
 51	        BigDecimal couponDiscount = calculateCouponDiscount(
 52	                request, productsSubtotal, shippingCost, itemQuantities);
 53	
 54	        BigDecimal insurance = calculateInsurance(request.getRegion(), productsSubtotal);
 55	
 56	        BigDecimal orderTotal = productsSubtotal
 57	                .subtract(couponDiscount)
 58	                .add(shippingCost)
 59	                .add(insurance);
 60	
 61	        PaymentInfo paymentInfo = calculatePayment(request, orderTotal);
 62	
 63	        BigDecimal nextPurchaseCredit = calculateClubCredit(request.getClubTier(), productsSubtotal);
 64	
 65	        boolean gift = shouldGiveGift(request.getClubTier(), request.getShippingMethod(), productsSubtotal);
 66	
 67	        OrderSummary summary = new OrderSummary();
 68	        summary.setProductsSubtotal(productsSubtotal);
 69	        summary.setCouponDiscount(couponDiscount);
 70	        summary.setShippingCost(shippingCost);
 71	        summary.setDeliveryDays(shippingInfo.days);
 72	        summary.setInsurance(insurance);
 73	        summary.setPaymentAdjustment(paymentInfo.adjustment);
 74	        summary.setFinalTotal(paymentInfo.finalTotal);
 75	        summary.setInstallments(paymentInfo.installments);
 76	        summary.setInstallmentAmount(paymentInfo.installmentAmount);
 77	        summary.setNextPurchaseCredit(nextPurchaseCredit);
 78	        summary.setGift(gift);
 79	
 80	        return summary;
 81	    }
 82	
 83	    private void validateRequest(CheckoutRequest request) {
 84	        if (request.getCustomer() == null ||
 85	            request.getCustomer().getCpf() == null ||
 86	            request.getCustomer().getEmail() == null) {
 87	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 88	        }
 89	
 90	        if (request.getItems() == null || request.getItems().isEmpty()) {
 91	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 92	        }
 93	
 94	        Set<String> skus = new HashSet<>();
 95	        for (var item : request.getItems()) {
 96	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
 97	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 98	            }
 99	            if (!skus.add(item.getSku())) {
100	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
101	            }
102	        }
103	
104	        if (request.getClubTier() == null) {
105	            throw new BusinessException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
106	        }
107	
108	        if (request.getRegion() == null) {
109	            throw new BusinessException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
110	        }
111	
112	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
113	            throw new BusinessException("INVALID_ZIP_CODE", HttpStatus.UNPROCESSABLE_ENTITY);
114	        }
115	
116	        if (request.getShippingMethod() == null) {
117	            throw new BusinessException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
118	        }
119	
120	        if (request.getCoupon() != null) {
121	            try {
122	                Coupon.valueOf(request.getCoupon().name());
123	            } catch (IllegalArgumentException e) {
124	                throw new BusinessException("INVALID_COUPON", HttpStatus.UNPROCESSABLE_ENTITY);
125	            }
126	        }
127	
128	        if (request.getPaymentMethod() == null) {
129	            throw new BusinessException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
130	        }
131	
132	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
133	        validateInstallments(request.getPaymentMethod(), installments);
134	    }
135	
136	    private void validateInstallments(PaymentMethod paymentMethod, int installments) {
137	        switch (paymentMethod) {
138	            case PIX, BANK_SLIP -> {
139	                if (installments != 1) {
140	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
141	                }
142	            }
143	            case CREDIT_CARD -> {
144	                if (installments < 1 || installments > 12) {
145	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
146	                }
147	            }
148	        }
149	    }
150	
151	    private Map<String, Product> loadProducts(CheckoutRequest request) {
152	        List<String> skus = request.getItems().stream()
153	                .map(CheckoutRequest.ItemRequest::getSku)
154	                .toList();
155	
156	        List<Product> products = productRepository.findAllById(skus);
157	
158	        if (products.size() != skus.size()) {
159	            throw new BusinessException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY);
160	        }
161	
162	        Map<String, Product> map = new HashMap<>();
163	        for (Product p : products) {
164	            map.put(p.getSku(), p);
165	        }
166	        return map;
167	    }
168	
169	    private Map<String, Integer> getItemQuantities(CheckoutRequest request) {
170	        Map<String, Integer> map = new HashMap<>();
171	        for (var item : request.getItems()) {
172	            map.put(item.getSku(), item.getQuantity());
173	        }
174	        return map;
175	    }
176	
177	    private void validateProducts(Map<String, Product> productMap, Map<String, Integer> itemQuantities) {
178	        for (var entry : itemQuantities.entrySet()) {
179	            Product product = productMap.get(entry.getKey());
180	
181	            if (product.getDiscontinued()) {
182	                throw new BusinessException("PRODUCT_DISCONTINUED", HttpStatus.UNPROCESSABLE_ENTITY);
183	            }
184	
185	            if (product.getStock() < entry.getValue()) {
186	                throw new BusinessException("INSUFFICIENT_STOCK", HttpStatus.UNPROCESSABLE_ENTITY);
187	            }
188	        }
189	    }
190	
191	    private BigDecimal calculateProductsSubtotal(Map<String, Product> productMap,
192	                                                  Map<String, Integer> itemQuantities) {
193	        BigDecimal total = ZERO;
194	        for (var entry : itemQuantities.entrySet()) {
195	            Product product = productMap.get(entry.getKey());
196	            BigDecimal itemTotal = product.getPrice()
197	                    .multiply(new BigDecimal(entry.getValue()))
198	                    .setScale(2, RoundingMode.HALF_EVEN);
199	            total = total.add(itemTotal);
200	        }
201	        return total.setScale(2, RoundingMode.HALF_EVEN);
202	    }
203	
204	    private ShippingInfo calculateShipping(CheckoutRequest request,
205	                                           Map<String, Product> productMap,
206	                                           Map<String, Integer> itemQuantities) {
207	        BigDecimal totalWeight = ZERO;
208	        for (var entry : itemQuantities.entrySet()) {
209	            Product product = productMap.get(entry.getKey());
210	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(entry.getValue()));
211	            totalWeight = totalWeight.add(itemWeight);
212	        }
213	
214	        switch (request.getShippingMethod()) {
215	            case STORE_PICKUP -> {
216	                return new ShippingInfo(ZERO, 1);
217	            }
218	            case COURIER -> {
219	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
220	                    throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
221	                }
222	                return new ShippingInfo(new BigDecimal("18.00"), 0);
223	            }
224	            case ECONOMY, EXPRESS -> {
225	                String service = request.getShippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
226	
227	                TransLogService.QuoteResult quote = transLogService.getQuote(
228	                        request.getZipCode(), totalWeight, service);
229	
230	                if (!quote.isAvailable()) {
231	                    throw new BusinessException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
232	                }
233	
234	                if (!quote.isServed()) {
235	                    throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
236	                }
237	
238	                int extraDays = getExtraDays(request.getRegion());
239	                return new ShippingInfo(quote.getPrice(), quote.getDays() + extraDays);
240	            }
241	            default -> throw new BusinessException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
242	        }
243	    }
244	
245	    private int getExtraDays(Region region) {
246	        return switch (region) {
247	            case NORTH -> 3;
248	            case NORTHEAST -> 2;
249	            default -> 0;
250	        };
251	    }
252	
253	    private BigDecimal calculateCouponDiscount(CheckoutRequest request,
254	                                                BigDecimal productsSubtotal,
255	                                                BigDecimal shippingCost,
256	                                                Map<String, Integer> itemQuantities) {
257	        if (request.getCoupon() == null) {
258	            return ZERO;
259	        }
260	
261	        BigDecimal discount = switch (request.getCoupon()) {
262	            case WELCOME10 -> {
263	                if (!isFirstPurchase(request.getCustomer().getCpf())) {
264	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
265	                }
266	                yield productsSubtotal.multiply(new BigDecimal("0.10"));
267	            }
268	            case MINUS50 -> {
269	                if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
270	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
271	                }
272	                yield new BigDecimal("50.00");
273	            }
274	            case FREESHIPPING -> {
275	                if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
276	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
277	                }
278	                yield shippingCost;
279	            }
280	            case BUY3PAY2 -> {
281	                BigDecimal buy3pay2Discount = ZERO;
282	                for (var entry : itemQuantities.entrySet()) {
283	                    if (entry.getValue() >= 3) {
284	                        Product product = productRepository.findById(entry.getKey()).orElseThrow();
285	                        int freeItems = entry.getValue() / 3;
286	                        buy3pay2Discount = buy3pay2Discount.add(
287	                                product.getPrice().multiply(new BigDecimal(freeItems)));
288	                    }
289	                }
290	                yield buy3pay2Discount;
291	            }
292	        };
293	
294	        discount = discount.setScale(2, RoundingMode.HALF_EVEN);
295	
296	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"))
297	                .setScale(2, RoundingMode.HALF_EVEN);
298	
299	        if (discount.compareTo(maxDiscount) > 0) {
300	            discount = maxDiscount;
301	        }
302	
303	        return discount;
304	    }
305	
306	    private boolean isFirstPurchase(String cpf) {
307	        long paidOrders = orderRepository.countByCustomerCpfAndStatusIn(
308	                cpf, OrderStatus.PAID, OrderStatus.SHIPPED, OrderStatus.DELIVERED);
309	        return paidOrders == 0;
310	    }
311	
312	    private BigDecimal calculateInsurance(Region region, BigDecimal productsSubtotal) {
313	        BigDecimal rate;
314	        BigDecimal limit;
315	
316	        switch (region) {
317	            case SOUTHEAST, SOUTH -> {
318	                rate = new BigDecimal("0.01");
319	                limit = null;
320	            }
321	            case MIDWEST -> {
322	                rate = new BigDecimal("0.015");
323	                limit = null;
324	            }
325	            case NORTH -> {
326	                rate = new BigDecimal("0.025");
327	                limit = new BigDecimal("30.00");
328	            }
329	            case NORTHEAST -> {
330	                rate = new BigDecimal("0.02");
331	                limit = new BigDecimal("30.00");
332	            }
333	            default -> {
334	                rate = ZERO;
335	                limit = null;
336	            }
337	        }
338	
339	        BigDecimal insurance = productsSubtotal.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
340	
341	        if (limit != null && insurance.compareTo(limit) > 0) {
342	            insurance = limit;
343	        }
344	
345	        return insurance;
346	    }
347	
348	    private PaymentInfo calculatePayment(CheckoutRequest request, BigDecimal orderTotal) {
349	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
350	
351	        BigDecimal adjustment;
352	        BigDecimal finalTotal;
353	        BigDecimal installmentAmount;
354	
355	        switch (request.getPaymentMethod()) {
356	            case PIX -> {
357	                if (request.getCoupon() == null) {
358	                    BigDecimal discount = orderTotal.multiply(new BigDecimal("0.05"))
359	                            .setScale(2, RoundingMode.HALF_EVEN);
360	                    adjustment = discount.negate();
361	                    finalTotal = orderTotal.subtract(discount);
362	                } else {
363	                    adjustment = ZERO;
364	                    finalTotal = orderTotal;
365	                }
366	                installmentAmount = finalTotal;
367	            }
368	            case BANK_SLIP -> {
369	                if (orderTotal.compareTo(new BigDecimal("1000.00")) > 0) {
370	                    throw new BusinessException("PAYMENT_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
371	                }
372	                BigDecimal fee = new BigDecimal("3.49");
373	                adjustment = fee;
374	                finalTotal = orderTotal.add(fee);
375	                installmentAmount = finalTotal;
376	            }
377	            case CREDIT_CARD -> {
378	                if (installments <= 3) {
379	                    adjustment = ZERO;
380	                    finalTotal = orderTotal;
381	                    installmentAmount = finalTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
382	                } else {
383	                    BigDecimal monthlyRate = new BigDecimal("0.0199");
384	                    BigDecimal onePlusRate = BigDecimal.ONE.add(monthlyRate);
385	                    BigDecimal factor = onePlusRate.pow(installments);
386	
387	                    installmentAmount = orderTotal.multiply(monthlyRate)
388	                            .divide(BigDecimal.ONE.subtract(BigDecimal.ONE.divide(factor, 10, RoundingMode.HALF_EVEN)),
389	                                    2, RoundingMode.HALF_EVEN);
390	
391	                    finalTotal = installmentAmount.multiply(new BigDecimal(installments));
392	                    adjustment = finalTotal.subtract(orderTotal);
393	                }
394	            }
395	            default -> throw new BusinessException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
396	        }
397	
398	        return new PaymentInfo(adjustment, finalTotal, installments, installmentAmount);
399	    }
400	
401	    private BigDecimal calculateClubCredit(ClubTier tier, BigDecimal productsSubtotal) {
402	        BigDecimal rate = switch (tier) {
403	            case BRONZE -> ZERO;
404	            case SILVER -> new BigDecimal("0.02");
405	            case GOLD -> new BigDecimal("0.05");
406	        };
407	
408	        return productsSubtotal.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
409	    }
410	
411	    private boolean shouldGiveGift(ClubTier tier, ShippingMethod shippingMethod, BigDecimal productsSubtotal) {
412	        if (tier != ClubTier.GOLD) {
413	            return false;
414	        }
415	
416	        if (shippingMethod == ShippingMethod.COURIER) {
417	            return false;
418	        }
419	
420	        return productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
421	    }
422	
423	    public OrderSummary applyGoldBenefits(OrderSummary summary, ClubTier tier, ShippingMethod shippingMethod) {
424	        if (tier == ClubTier.GOLD && shippingMethod != ShippingMethod.COURIER) {
425	            summary.setShippingCost(ZERO);
426	        }
427	        return summary;
428	    }
429	
430	    private static class ShippingInfo {
431	        final BigDecimal cost;
432	        final int days;
433	
434	        ShippingInfo(BigDecimal cost, int days) {
435	            this.cost = cost;
436	            this.days = days;
437	        }
438	    }
439	
440	    private static class PaymentInfo {
441	        final BigDecimal adjustment;
442	        final BigDecimal finalTotal;
443	        final int installments;
444	        final BigDecimal installmentAmount;
445	
446	        PaymentInfo(BigDecimal adjustment, BigDecimal finalTotal, int installments, BigDecimal installmentAmount) {
447	            this.adjustment = adjustment;
448	            this.finalTotal = finalTotal;
449	            this.installments = installments;
450	            this.installmentAmount = installmentAmount;
451	        }
452	    }
453	}
454	package com.loja.orderservice.service;
