456	import com.fasterxml.jackson.annotation.JsonProperty;
457	import org.springframework.beans.factory.annotation.Value;
458	import org.springframework.stereotype.Service;
459	import org.springframework.web.client.RestClient;
460	
461	import java.math.BigDecimal;
462	import java.math.RoundingMode;
463	import java.time.Duration;
464	
465	@Service
466	public class TransLogService {
467	
468	    private final String translogUrl;
469	    private final RestClient restClient;
470	
471	    public TransLogService(
472	            @Value("${translog.url}") String translogUrl,
473	            @Value("${translog.timeout.seconds}") int timeoutSeconds) {
474	        this.translogUrl = translogUrl;
475	        this.restClient = RestClient.builder()
476	                .baseUrl(translogUrl)
477	                .build();
478	    }
479	
480	    public QuoteResult getQuote(String zipCode, BigDecimal weightKg, String service) {
481	        try {
482	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
483	
484	            String url = String.format("/v2/quote?zip=%s&weight_g=%d&service=%s",
485	                    zipCode, weightGrams, service);
486	
487	            TransLogResponse response = restClient.get()
488	                    .uri(url)
489	                    .retrieve()
490	                    .body(TransLogResponse.class);
491	
492	            if (response == null) {
493	                return QuoteResult.unavailable();
494	            }
495	
496	            if (response.error != null) {
497	                if ("ZIP_NOT_SERVED".equals(response.error)) {
498	                    return QuoteResult.notServed();
499	                }
500	                return QuoteResult.unavailable();
501	            }
502	
503	            if (response.priceCents == null || response.etaHours == null) {
504	                return QuoteResult.unavailable();
505	            }
506	
507	            BigDecimal price = new BigDecimal(response.priceCents)
508	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
509	
510	            int days = (int) Math.ceil(response.etaHours / 24.0);
511	
512	            return QuoteResult.success(price, days);
513	
514	        } catch (Exception e) {
515	            return QuoteResult.unavailable();
516	        }
517	    }
518	
519	    public static class QuoteResult {
520	        private final boolean available;
521	        private final boolean served;
522	        private final BigDecimal price;
523	        private final int days;
524	
525	        private QuoteResult(boolean available, boolean served, BigDecimal price, int days) {
526	            this.available = available;
527	            this.served = served;
528	            this.price = price;
529	            this.days = days;
530	        }
531	
532	        public static QuoteResult success(BigDecimal price, int days) {
533	            return new QuoteResult(true, true, price, days);
534	        }
535	
536	        public static QuoteResult notServed() {
537	            return new QuoteResult(true, false, null, 0);
538	        }
539	
540	        public static QuoteResult unavailable() {
541	            return new QuoteResult(false, false, null, 0);
542	        }
543	
544	        public boolean isAvailable() {
545	            return available;
546	        }
547	
548	        public boolean isServed() {
549	            return served;
550	        }
551	
552	        public BigDecimal getPrice() {
553	            return price;
554	        }
555	
556	        public int getDays() {
557	            return days;
558	        }
559	    }
560	
561	    private static class TransLogResponse {
562	        @JsonProperty("price_cents")
563	        private Integer priceCents;
564	
565	        @JsonProperty("eta_hours")
566	        private Integer etaHours;
567	
568	        private String error;
569	
570	        public Integer getPriceCents() {
571	            return priceCents;
572	        }
573	
574	        public void setPriceCents(Integer priceCents) {
575	            this.priceCents = priceCents;
576	        }
577	
578	        public Integer getEtaHours() {
579	            return etaHours;
580	        }
581	
582	        public void setEtaHours(Integer etaHours) {
583	            this.etaHours = etaHours;
584	        }
585	
586	        public String getError() {
587	            return error;
588	        }
589	
590	        public void setError(String error) {
591	            this.error = error;
592	        }
593	    }
594	}

