 83	    private void validateRequest(CheckoutRequest request) {
 84	        if (request.getCustomer() == null ||
 85	            request.getCustomer().getCpf() == null ||
 86	            request.getCustomer().getEmail() == null) {
 87	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 88	        }
 89	
 90	        if (request.getItems() == null || request.getItems().isEmpty()) {
 91	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 92	        }
 93	
 94	        Set<String> skus = new HashSet<>();
 95	        for (var item : request.getItems()) {
 96	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
 97	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
 98	            }
 99	            if (!skus.add(item.getSku())) {
100	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
101	            }
102	        }
103	
104	        if (request.getClubTier() == null) {
105	            throw new BusinessException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
106	        }
107	
108	        if (request.getRegion() == null) {
109	            throw new BusinessException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
110	        }
111	
112	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
113	            throw new BusinessException("INVALID_ZIP_CODE", HttpStatus.UNPROCESSABLE_ENTITY);
114	        }
115	
116	        if (request.getShippingMethod() == null) {
117	            throw new BusinessException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
118	        }
119	
120	        if (request.getCoupon() != null) {
121	            try {
122	                Coupon.valueOf(request.getCoupon().name());
123	            } catch (IllegalArgumentException e) {
124	                throw new BusinessException("INVALID_COUPON", HttpStatus.UNPROCESSABLE_ENTITY);
125	            }
126	        }
127	
128	        if (request.getPaymentMethod() == null) {
129	            throw new BusinessException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
130	        }
131	
132	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
133	        validateInstallments(request.getPaymentMethod(), installments);
134	    }
135	
136	    private void validateInstallments(PaymentMethod paymentMethod, int installments) {
137	        switch (paymentMethod) {
138	            case PIX, BANK_SLIP -> {
139	                if (installments != 1) {
140	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
141	                }
142	            }
143	            case CREDIT_CARD -> {
144	                if (installments < 1 || installments > 12) {
145	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
146	                }
147	            }
148	        }
149	    }
