292	import com.loja.orderservice.dto.NotificationResponse;
293	import com.loja.orderservice.entity.Notification;
294	import com.loja.orderservice.exception.BusinessException;
295	import com.loja.orderservice.model.NotificationType;
296	import com.loja.orderservice.repository.CustomerRepository;
297	import com.loja.orderservice.repository.NotificationRepository;
298	import org.springframework.http.HttpStatus;
299	import org.springframework.stereotype.Service;
300	import org.springframework.transaction.annotation.Transactional;
301	
302	import java.util.List;
303	import java.util.stream.Collectors;
304	
305	@Service
306	public class NotificationService {
307	
308	    private final NotificationRepository notificationRepository;
309	    private final CustomerRepository customerRepository;
310	
311	    public NotificationService(NotificationRepository notificationRepository,
312	                               CustomerRepository customerRepository) {
313	        this.notificationRepository = notificationRepository;
314	        this.customerRepository = customerRepository;
315	    }
316	
317	    @Transactional
318	    public void notifyCustomer(String cpf, NotificationType type, Long orderId) {
319	        Notification notification = new Notification(cpf, type, orderId);
320	        notificationRepository.save(notification);
321	    }
322	
323	    @Transactional(readOnly = true)
324	    public List<NotificationResponse> getCustomerNotifications(String cpf) {
325	        if (!customerRepository.existsById(cpf)) {
326	            throw new BusinessException("CUSTOMER_NOT_FOUND", HttpStatus.NOT_FOUND);
327	        }
328	
329	        List<Notification> notifications = notificationRepository.findByCustomerCpfOrderByIdAsc(cpf);
330	
331	        return notifications.stream()
332	                .map(this::toResponse)
333	                .collect(Collectors.toList());
334	    }
335	
336	    @Transactional
337	    public NotificationResponse markAsRead(Long id) {
338	        Notification notification = notificationRepository.findById(id)
339	                .orElseThrow(() -> new BusinessException("NOTIFICATION_NOT_FOUND", HttpStatus.NOT_FOUND));
340	
341	        notification.markAsRead();
342	        notificationRepository.save(notification);
343	
344	        return toResponse(notification);
345	    }
346	
347	    private NotificationResponse toResponse(Notification notification) {
348	        NotificationResponse response = new NotificationResponse();
349	        response.setId(notification.getId());
350	        response.setType(notification.getType());
351	        response.setOrderId(notification.getOrderId());
352	        response.setStatus(notification.getStatus());
353	        return response;
354	    }
355	}
