mkdir -p /tmp/run/stub && cat > /tmp/run/stub/Stub.java <<'EOF'
import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class Stub {
    record Rule(int status, String body, long delayMs) {}
    static final Map<String, Rule> rules = new ConcurrentHashMap<>();
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());

    static Map<String,String> q(String query) {
        Map<String,String> m = new HashMap<>();
        if (query == null) return m;
        for (String p : query.split("&")) { String[] kv = p.split("=", 2); m.put(URLDecoder.decode(kv[0], StandardCharsets.UTF_8), kv.length > 1 ? URLDecoder.decode(kv[1], StandardCharsets.UTF_8) : ""); }
        return m;
    }
    static void send(HttpExchange ex, int status, String body) throws IOException {
        byte[] b = body.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(status, b.length);
        ex.getResponseBody().write(b); ex.close();
    }
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        // POST /set?key=ZIP:SERVICE&status=200&delay=0  body = response body
        s.createContext("/set", ex -> {
            Map<String,String> m = q(ex.getRequestURI().getRawQuery());
            String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            rules.put(m.get("key"), new Rule(Integer.parseInt(m.getOrDefault("status","200")), body, Long.parseLong(m.getOrDefault("delay","0"))));
            send(ex, 200, "ok");
        });
        s.createContext("/log", ex -> { String out; synchronized (log) { out = String.join("\n", log); log.clear(); } send(ex, 200, out); });
        s.createContext("/v2/quote", ex -> {
            Map<String,String> m = q(ex.getRequestURI().getRawQuery());
            log.add(ex.getRequestURI().toString());
            Rule r = rules.get(m.get("zip") + ":" + m.get("service"));
            if (r == null) r = rules.get(m.get("zip"));
            if (r == null) r = new Rule(200, "{\"price_cents\":3310,\"eta_hours\":41}", 0);
            if (r.delayMs() > 0) try { Thread.sleep(r.delayMs()); } catch (InterruptedException e) {}
            send(ex, r.status(), r.body());
        });
        s.start();
        System.out.println("stub up");
    }
}
EOF
cd /tmp/run/stub && (nohup java Stub.java 9099 > stub.log 2>&1 &) ; sleep 3; cat stub.log; curl -s 'localhost:9099/v2/quote?zip=1&weight_g=1&service=EXP'

